def causal_avg(x):
    return np.cumsum(x, axis=0) / np.arange(1, len(x) + 1)[:, None]


def anti_causal(x):
    return np.cumsum(x[::-1], axis=0)[::-1] / np.arange(len(x), 0, -1)[:, None]


def row_norm(x):
    mu = x.mean(-1, keepdims=True)
    return (x - mu) / np.sqrt(((x - mu) ** 2).mean(-1, keepdims=True) + 1e-5)


def zero_out(x):
    return np.zeros_like(x)

