import base64
import json
import numpy as np


def _load(path):
    raw = json.load(open(path))
    arr = {k: np.frombuffer(base64.b64decode(v['b64']), dtype='<f4').reshape(v['shape']).astype(float) for k, v in raw.items() if isinstance(v, dict) and 'b64' in v}
    keys = ('ln1_g', 'ln1_b', 'Wq', 'bq', 'Wk', 'bk', 'Wv', 'bv', 'Wo', 'bo', 'ln2_g', 'ln2_b', 'W1', 'b1', 'W2', 'b2')
    m = {k: v for k, v in arr.items() if not k.startswith('blocks.')}
    m['blocks'] = [{k: arr[f'blocks.{i}.{k}'] for k in keys} for i in range(2)]
    return m


REV = _load('sequence-reverse.json')
