def planted(V, T, d, dm, nb, seed):
    g = np.random.default_rng(seed)
    blocks = []
    for _ in range(nb):
        p = {k: g.standard_normal((d, d)) / np.sqrt(d) for k in ('Wq', 'Wk', 'Wv', 'Wo')}
        p['W1'] = g.standard_normal((d, dm)) / np.sqrt(d)
        p['W2'] = g.standard_normal((dm, d)) / np.sqrt(dm)
        for k, n in (('bq', d), ('bk', d), ('bv', d), ('bo', d), ('b1', dm), ('b2', d), ('ln1_b', d), ('ln2_b', d)):
            p[k] = 0.1 * g.standard_normal(n)
        p['ln1_g'] = 1 + 0.2 * g.standard_normal(d)
        p['ln2_g'] = 1 + 0.2 * g.standard_normal(d)
        blocks.append(p)
    return {'E': g.standard_normal((V, d)), 'P': 0.5 * g.standard_normal((T, d)), 'blocks': blocks,
            'lnf_g': 1 + 0.2 * g.standard_normal(d), 'lnf_b': 0.1 * g.standard_normal(d),
            'U': g.standard_normal((d, V)) / np.sqrt(d), 'c': 0.1 * g.standard_normal(V)}


